    rewrite (srun_sound tm false true chz_1RB1LA_1LC1RD_1LC1LA_0LC0RB Z0_1RB1LA_1LC1RD_1LC1LA_0LC0RB Z1_1RB1LA_1LC1RD_1LC1LA_0LC0RB 0 4
