Lemma gsi_1RB1LA_1LC1RD_1RC1LA_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_1LC1RD_1RC1LA_0LA0RB.
