Definition B0_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S0] 1 1 [S1]) S0 (mkS [S1;S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StA *)
Definition Cin_1RB1LA_1RC0LD_0LA0RB_0RC1LB (v : positive) : cconf := (StA, (Ip v ++ [S1], S0, [S1])).
Local Notation Cin := Cin_1RB1LA_1RC0LD_0LA0RB_0RC1LB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition AI1_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chn_1RB1LA_1RC0LD_0LA0RB_0RC1LB : list lstep := [SWin 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3].

Lemma run_inner_1RB1LA_1RC0LD_0LA0RB_0RC1LB : srun tm false true chn_1RB1LA_1RC0LD_0LA0RB_0RC1LB AI0_1RB1LA_1RC0LD_0LA0RB_0RC1LB = Some (AI1_1RB1LA_1RC0LD_0LA0RB_0RC1LB, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chb_1RB1LA_1RC0LD_0LA0RB_0RC1LB : list lstep := [SWin 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3].

Lemma run_boot_1RB1LA_1RC0LD_0LA0RB_0RC1LB : srun tm true true chb_1RB1LA_1RC0LD_0LA0RB_0RC1LB B0_1RB1LA_1RC0LD_0LA0RB_0RC1LB = Some (BB1_1RB1LA_1RC0LD_0LA0RB_0RC1LB, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_1RC0LD_0LA0RB_0RC1LB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_1RB1LA_1RC0LD_0LA0RB_0RC1LB : list lstep := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 3; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1LA_1RC0LD_0LA0RB_0RC1LB : srun tm true true che_1RB1LA_1RC0LD_0LA0RB_0RC1LB BE0_1RB1LA_1RC0LD_0LA0RB_0RC1LB = Some (B1_1RB1LA_1RC0LD_0LA0RB_0RC1LB, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB1LA_1RC0LD_0LA0RB_0RC1LB.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_1RC0LD_0LA0RB_0RC1LB, cden, A0_1RB1LA_1RC0LD_0LA0RB_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ip q0 ++ [S0]) [] j A1_1RB1LA_1RC0LD_0LA0RB_0RC1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_1RC0LD_0LA0RB_0RC1LB, cden, A1_1RB1LA_1RC0LD_0LA0RB_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 12), (cden (Ip q0 ++ [S0]) [] j A1_1RB1LA_1RC0LD_0LA0RB_0RC1LB).
  split; [lia|]. split; [| exact (gei_1RB1LA_1RC0LD_0LA0RB_0RC1LB p j q0 E)].
  rewrite (gsi_1RB1LA_1RC0LD_0LA0RB_0RC1LB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_1RC0LD_0LA0RB_0RC1LB A0_1RB1LA_1RC0LD_0LA0RB_0RC1LB A1_1RB1LA_1RC0LD_0LA0RB_0RC1LB 4 12
           run_int_1RB1LA_1RC0LD_0LA0RB_0RC1LB (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1RC0LD_0LA0RB_0RC1LB.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_1RB1LA_1RC0LD_0LA0RB_0RC1LB, cden, B0_1RB1LA_1RC0LD_0LA0RB_0RC1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1RC0LD_0LA0RB_0RC1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1RC0LD_0LA0RB_0RC1LB
             = (StA, (rep [S1;S0] (S j) ++ [S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, B1_1RB1LA_1RC0LD_0LA0RB_0RC1LB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB1LA_1RC0LD_0LA0RB_0RC1LB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LA_1RC0LD_0LA0RB_0RC1LB. reflexivity.
Qed.

Lemma gsn_1RB1LA_1RC0LD_0LA0RB_0RC1LB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1LA_1RC0LD_0LA0RB_0RC1LB.
