Lemma gei_1RB1LA_1RC0LD_0LA0RB_1RB1LB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ip q0 ++ [S0]) [] j A1_1RB1LA_1RC0LD_0LA0RB_1RB1LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_1RC0LD_0LA0RB_1RB1LB, cden, A1_1RB1LA_1RC0LD_0LA0RB_1RB1LB; cbn [c_st c_l c_h c_r].
