(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1RC0LD_1LA1RB_0RC1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB1LA_1RC0LD_1LA1RB_0RC1LD.
