Lemma geo_1RB1LA_1RC0LD_1LA1RB_0RC1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1RC0LD_1LA1RB_0RC1LD) = lift (Cc (Pos.succ p)).
