    apply (lap_of_run tm Cc true true cho_1RB1LA_1RC0RB_0LD0LB_1LA1LC B0_1RB1LA_1RC0RB_0LD0LB_1LA1LC B1_1RB1LA_1RC0RB_0LD0LB_1LA1LC 2 12 p j' [] []).
