Qed.

Lemma lapi_1RB1LA_1RC0RB_1LD1LD_1RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (2 * j + 10). split; [lia|].
  rewrite (gsi_1RB1LA_1RC0RB_1LD1LD_1RA0LC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LA_1RC0RB_1LD1LD_1RA0LC A0_1RB1LA_1RC0RB_1LD1LD_1RA0LC A1_1RB1LA_1RC0RB_1LD1LD_1RA0LC 2 10
             run_int_1RB1LA_1RC0RB_1LD1LD_1RA0LC (Kp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_1RC0RB_1LD1LD_1RA0LC p j q0 E).
Qed.

Lemma gso_1RB1LA_1RC0RB_1LD1LD_1RA0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1RC0RB_1LD1LD_1RA0LC.
Proof.
