Lemma gsi_1RB1LA_1RC0RD_0LA0RB_0LC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j A0_1RB1LA_1RC0RD_0LA0RB_0LC0LA.
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_1RC0RD_0LA0RB_0LC0LA, cden, A0_1RB1LA_1RC0RD_0LA0RB_0LC0LA; cbn [c_st c_l c_h c_r].
