(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_1RC0RD_0LA0RB_0LC0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1LA_1RC0RD_0LA0RB_0LC0LA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (8 * j + 9), (cden [] [] j BB1_1RB1LA_1RC0RD_0LA0RB_0LC0LA).
      split; [lia|]. split; [| exact (gbo_1RB1LA_1RC0RD_0LA0RB_0LC0LA j)].
      rewrite (gso_1RB1LA_1RC0RD_0LA0RB_0LC0LA p j E).
      exact (srun_sound tm true true chb_1RB1LA_1RC0RD_0LA0RB_0LC0LA B0_1RB1LA_1RC0RD_0LA0RB_0LC0LA BB1_1RB1LA_1RC0RD_0LA0RB_0LC0LA 8 9
               run_boot_1RB1LA_1RC0RD_0LA0RB_0LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_1RC0RD_0LA0RB_0LC0LA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (8 * j + 17), (cden [] [] j BM1_1RB1LA_1RC0RD_0LA0RB_0LC0LA).
