      exact (srun_sound tm true true chm_1RB1LA_1RC0RD_0LA0RB_0LC0LA BM0_1RB1LA_1RC0RD_0LA0RB_0LC0LA BM1_1RB1LA_1RC0RD_0LA0RB_0LC0LA 8 17
               run_shift_1RB1LA_1RC0RD_0LA0RB_0LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (8 * j + 22), (cden [] [] j B1_1RB1LA_1RC0RD_0LA0RB_0LC0LA).
    split; [| exact (geo_1RB1LA_1RC0RD_0LA0RB_0LC0LA p j E)].
    rewrite (gxi2_1RB1LA_1RC0RD_0LA0RB_0LC0LA j).
    exact (srun_sound tm true true che_1RB1LA_1RC0RD_0LA0RB_0LC0LA BE0_1RB1LA_1RC0RD_0LA0RB_0LC0LA B1_1RB1LA_1RC0RD_0LA0RB_0LC0LA 8 22
             run_exit_1RB1LA_1RC0RD_0LA0RB_0LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_1RC0RD_0LA0RB_0LC0LA : forall p, exists n c',
