(** 1RB1LA_1RC0RD_0LD0RB_1LB0LA *)
Definition tm_1RB1LA_1RC0RD_0LD0RB_1LB0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_1RC0RD_0LD0RB_1LB0LA : list Instr := [].
Definition tmw_1RB1LA_1RC0RD_0LD0RB_1LB0LA : TM := tm_wrap_trs tm_1RB1LA_1RC0RD_0LD0RB_1LB0LA pins_1RB1LA_1RC0RD_0LD0RB_1LB0LA.
