Definition chi_1RB1LA_1RC0RD_0LD0RB_1LB0LA : list lstep := [SWin 1; SWinR 9; SCycL 3 0; SWin 6; SCycR 5].

Lemma run_int_1RB1LA_1RC0RD_0LD0RB_1LB0LA : srun tm false true chi_1RB1LA_1RC0RD_0LD0RB_1LB0LA A0_1RB1LA_1RC0RD_0LD0RB_1LB0LA = Some (A1_1RB1LA_1RC0RD_0LD0RB_1LB0LA, 8, 16).
