(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_1RB1LA_1RC0RD_0LD0RB_1LB0LA : forall j, lift (cden [] [] j BB1_1RB1LA_1RC0RD_0LD0RB_1LB0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_1RC0RD_0LD0RB_1LB0LA = (StA, (rep [S0;S1;S1] j ++ [S1], S0, (([S0;S1;S1]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_1RC0RD_0LD0RB_1LB0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S0;S1;S1] j ++ [S1], S0, [S0;S1;S1]))).
  { unfold Cin_1RB1LA_1RC0RD_0LD0RB_1LB0LA. rewrite epow2_1RB1LA_1RC0RD_0LD0RB_1LB0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_1RC0RD_0LD0RB_1LB0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_1RC0RD_0LD0RB_1LB0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB1LA_1RC0RD_0LD0RB_1LB0LA.
Proof.
  intro j.
  destruct (Alph_011_111_1.cview_none_Alph_011_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_1RC0RD_0LD0RB_1LB0LA, cden, BM0_1RB1LA_1RC0RD_0LD0RB_1LB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

