Lemma gen2_1RB1LA_1RC0RD_0LD0RB_1LB0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_011_111_1 q0 ++ []) [] i AI21_1RB1LA_1RC0RD_0LD0RB_1LB0LA) = lift (Cin2 (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 v i q0 E) as (_ & H2).
  unfold Cin2_1RB1LA_1RC0RD_0LD0RB_1LB0LA, cden, AI21_1RB1LA_1RC0RD_0LD0RB_1LB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0;S1;S1;S1;S0;S0]) with ((([S0;S1;S1;S1]) ++ [S0]) ++ [S0]).
