(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1RC1RB_1LD1RA_0RB0LD : forall t, ~ In t pins_1RB1LA_1RC1RB_1LD1RA_0RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_1RC1RB_1LD1RA_0RB0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RB_1LD1RA_0RB0LD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RB_1LD1RA_0RB0LD [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RB_1LD1RA_0RB0LD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RB_1LD1RA_0RB0LD [SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_1RC1RB_1LD1RA_0RB0LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RB_1LD1RA_0RB0LD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RB_1LD1RA_0RB0LD [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_1RC1RB_1LD1RA_0RB0LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RB_1LD1RA_0RB0LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RB_1LD1RA_0RB0LD [SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_1RC1RB_1LD1RA_0RB0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LA_1RC1RB_1LD1RA_0RB0LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

