    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RC_0LA0RD_0LB1RC [SWinR 2; SCycL 2 0; SWin 2; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_1RC1RC_0LA0RD_0LB1RC : NeverQuasiHaltsTr tm_1RB1LA_1RC1RC_0LA0RD_0LB1RC.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_1RC1RC_0LA0RD_0LB1RC pins_1RB1LA_1RC1RC_0LA0RD_0LB1RC Cc 1).
