(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A0_1RB1LA_1RC1RC_0LA1RD_0LB0RB.
Proof.
