  unfold Cc_1RB1LA_1RC1RC_0LA1RD_0LB0RB, cden, A0_1RB1LA_1RC1RC_0LA1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A1_1RB1LA_1RC1RC_0LA1RD_0LB0RB = Cc (Pos.succ p).
