  rewrite (srun_sound tm false true chi_1RB1LA_1RC1RC_0LA1RD_0LB0RB A0_1RB1LA_1RC1RC_0LA1RD_0LB0RB A1_1RB1LA_1RC1RC_0LA1RD_0LB0RB 6 4
             run_int_1RB1LA_1RC1RC_0LA1RD_0LB0RB (Ap_Alph_101_111_11 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_1RC1RC_0LA1RD_0LB0RB p j q0 E).
Qed.

Lemma gso_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1RC1RC_0LA1RD_0LB0RB.
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (H1 & _).
  unfold Cc_1RB1LA_1RC1RC_0LA1RD_0LB0RB, cden, B0_1RB1LA_1RC1RC_0LA1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1RC1RC_0LA1RD_0LB0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1RC1RC_0LA1RD_0LB0RB
             = (StC, (rep [S1;S0;S1] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB1LA_1RC1RC_0LA1RD_0LB0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0;S1] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_1RC1RC_0LA1RD_0LB0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_1RC1RC_0LA1RD_0LB0RB. reflexivity.
Qed.

Lemma gsn_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI0_1RB1LA_1RC1RC_0LA1RD_0LB0RB.
