  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_1RC1RC_0LA1RD_0LB0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 8), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_1RB1LA_1RC1RC_0LA1RD_0LB0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_1RC1RC_0LA1RD_0LB0RB v i q0 E)].
  rewrite (gsn_1RB1LA_1RC1RC_0LA1RD_0LB0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_1RC1RC_0LA1RD_0LB0RB AI0_1RB1LA_1RC1RC_0LA1RD_0LB0RB AI1_1RB1LA_1RC1RC_0LA1RD_0LB0RB 6 8
           run_inner_1RB1LA_1RC1RC_0LA1RD_0LB0RB (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
