(** ** The certificate *)

Definition A0_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
