Definition B0_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S0;S1] 1 1 [S1;S0;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_101_111_11 at StC *)
Definition Cin_1RB1LA_1RC1RC_0LA1RD_0RB0LC (v : positive) : cconf := (StC, (Ap_Alph_101_111_11 v ++ [S1;S1;S1], S0, [])).
Local Notation Cin := Cin_1RB1LA_1RC1RC_0LA1RD_0RB0LC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_1RC1RC_0LA1RD_0RB0LC : forall n, Ap_Alph_101_111_11 (pow2 n) = rep [S1;S0;S1] n ++ [S1;S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_1RC1RC_0LA1RD_0RB0LC : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1LA_1RC1RC_0LA1RD_0RB0LC : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LA_1RC1RC_0LA1RD_0RB0LC : srun tm false true chn_1RB1LA_1RC1RC_0LA1RD_0RB0LC AI0_1RB1LA_1RC1RC_0LA1RD_0RB0LC = Some (AI1_1RB1LA_1RC1RC_0LA1RD_0RB0LC, 8, 4).
