    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_1RC1RC_0LA1RD_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_1RC1RC_0LA1RD_0RB0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RC_0LA1RD_0RB0LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RC_0LA1RD_0RB0LC [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 8; SCycR 5; SWin 1; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_1RC1RC_0LA1RD_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_1RC1RC_0LA1RD_0RB0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RC_0LA1RD_0RB0LC (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RC_0LA1RD_0RB0LC [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RC_0LA1RD_0RB0LC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RC_0LA1RD_0RB0LC [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 6] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1RC1RC_0LA1RD_0RB0LC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1RC1RC_0LA1RD_0RB0LC [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_1RC1RC_0LA1RD_0RB0LC : NeverQuasiHaltsTr tm_1RB1LA_1RC1RC_0LA1RD_0RB0LC.
Proof.
