  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1RC1RC_0LA1RD_1RB0RB B0_1RB1LA_1RC1RC_0LA1RD_1RB0RB B1_1RB1LA_1RC1RC_0LA1RD_1RB0RB 6 34 p j' [] []).
