    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_1RC1RD_0LA0RB_0LD1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
